[HttpPost("SubmitDraft")]
public async Task SubmitDraft([FromBody] Guid draftId)
{
 var userId = GetUserId();
 var draft = await service.GetAsync(draftId, userId);

 var correlationId = Guid.NewGuid();
 var createProperty = draft.ToCreateProperty(correlationId);

 await publishEndpoint.Publish(new BecomeHostStarted(correlationId, createProperty));
 await service.CompleteDraft(draftId, userId);
}
```
