using Contracts.Events;
using Contracts.Messages;

namespace Orchestrator.Api.Extensions;

public static class BecomeHostStartedExtensions
{
 public static CreateProperty ToCreateProperty(this BecomeHostStarted started, Guid correlationId)
 {
 return new CreateProperty(
 CorrelationId: correlationId,
 HostId: started.HostId,
 Name: started.Name,
 PropertyTypeId: started.PropertyTypeId,
 Address: started.Address,
 City: started.City,
 Country: started.Country,
 PostCode: started.PostCode,
 CheckInTimeFrom: started.CheckInTimeFrom,
 CheckInTimeUntil: started.CheckInTimeUntil,
 CheckOutTimeFrom: started.CheckOutTimeFrom,
 CheckOutTimeUntil: started.CheckOutTimeUntil,
 PetAllowed: started.PetAllowed,
 SmokingAllowed: started.SmokingAllowed,
 PartyAllowed: started.PartyAllowed,
 AgeRestriction: started.AgeRestriction,
 FloorNumber: started.FloorNumber
 );
 }
}
```
</augment_code_snippet>

