3a75c15ff905e","file":{"repoRoot":"","pathName":"services/PropertyService/Property.Api/appsettings.json"}}]},{"status":"success","request_id":"260093ae-f9c5-4a01-894e-3ac4ed81eb39","request_message":"t tưởng là khi FE gửi draft về thì phải map từ draft sang create property ","rich_text_json_repr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"t tưởng là khi FE gửi draft về thì phải map từ draft sang create property "}]}]},"mentioned_items":[],"structured_output_nodes":[{"id":1,"type":0,"content":"## Đúng rồi! Bạn cần map từ Draft → BecomeHostStarted

### **Flow đúng:**

```
1. FE gửi draftId → Controller
2. Controller lấy draft từ Redis
3. Map draft → BecomeHostStarted event 
4. Publish event → Khởi tạo Saga
5. Saga map BecomeHostStarted → CreateProperty message
```

### **Trong Controller:**

<augment_code_snippet path="services/OrchestratorService/Orchestrator.Api/Controllers/BecomeHostDraftController.cs" mode="EDIT">
```csharp
[HttpPost("SubmitDraft")]
public async Task CompleteDraft([FromBody] Guid draftId)
{
 var userId = GetUserId();
 var draft = await service.GetAsync(draftId, userId);
 var correlationId = Guid.NewGuid();

 // Map draft → BecomeHostStarted
 var becomeHostStarted = draft.ToBecomeHostStarted(correlationId);

 // Publish để khởi tạo saga
 await publisher.Publish(becomeHostStarted);

 await service.CompleteDraft(draftId, userId);
}
```
</augment_code_snippet>

### **Extension method cho Draft:**

<augment_code_snippet path="services/OrchestratorService/Orchestrator.Api/Extensions/BecomeHostDraftExtensions.cs" mode="EDIT">
```csharp
public static BecomeHostStarted ToBecomeHostStarted(this BecomeHostDraft draft, Guid correlationId)
{
 if (draft.LocationDto == null)
 throw new InvalidOperationException("LocationDto is required");

 if (draft.HouseRuleDto == null)
 throw new InvalidOperationException("HouseRuleDto is required");

 return new BecomeHostStarted(
 correlationId,
 draft.UserId,
 draft.PropertyName,
 draft.PropertyTypeId,
 draft.LocationDto.Address,
 draft.LocationDto.City,
 draft.LocationDto.Country,
 draft.LocationDto.PostCode,
 draft.HouseRuleDto.CheckInTimeFrom,
 draft.HouseRuleDto.CheckInTimeUntil,
 draft.HouseRuleDto.CheckOutTimeFrom,
 draft.HouseRuleDto.CheckOutTimeUntil,
 draft.HouseRuleDto.PetAllowed,
 draft.HouseRuleDto.SmokingAllowed,
 draft.HouseRuleDto.PartyAllowed,
 draft.HouseRuleDto.AgeRestriction,
 draft.HouseRuleDto.FloorNumber
 );
}
```
</augment_code_snippet>

### **Trong Saga:**

<augment_code_snippet path="services/OrchestratorService/Orchestrator.Api/Sagas/BecomeHostSaga.cs" mode="EDIT">
```csharp
Initially(
 When(Started)
 .Then(context => { context.Saga.HostId = context.Message.HostId; })
 .TransitionTo(CreatingProperty)
 .Publish(context => context.Message.ToCreateProperty(context.Saga.CorrelationId))
);
```
</augment_code_snippet>

**Vậy bạn cần 2 mapping methods:**
1. `Draft → BecomeHostStarted` (trong Controller)
2. `BecomeHostStarted → CreateProperty` (trong Saga)
