ces/IdentityService/Identity.Application/Services/JwtService.cs"}},{"char_start":"1579","char_end":"2553","blob_name":"3121e1985c968c99d26109c5991af8bc8c140a8c718217fd331a1bc2c53ba5a7","file":{"repoRoot":"","pathName":"services/IdentityService/Identity.Api/Middlewares/TokenValidateMiddleware.cs"}},{"char_start":"5817","char_end":"6710","blob_name":"d84de8127c4f6bafecb3452344248a59a947013c316f6c81dc1d6cd50457139a","file":{"repoRoot":"","pathName":"web-ui/src/app/page.tsx"}},{"char_start":"0","char_end":"640","blob_name":"f78c93d268de9894f64855afeb70a8438680d3b8c6daa8b6ab18a92156fd90a6","file":{"repoRoot":"","pathName":"shared/BuildingBlocks/Commons/Result.cs"}},{"char_start":"0","char_end":"620","blob_name":"a0ad8e74900cdcb3e1ebda749924e96b17253022b00118b90002a9dfc641639a","file":{"repoRoot":"","pathName":"services/OrchestratorService/Orchestrator.Api/Drafts/BecomeHostDraft.cs"}},{"char_start":"0","char_end":"236","blob_name":"d1a2bb83dc972c6321614bb57790cea67b895926a1a5ea0e3d5c036e37be1d92","file":{"repoRoot":"","pathName":"shared/BuildingBlocks/Interfaces/IEntity.cs"}}]},{"status":"success","request_id":"ef0caf9a-921e-4e6a-b9b4-c8293f52462d","request_message":"thế nếu tôi để Draft vào trong sagadata thì sao ","rich_text_json_repr":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"thế nếu tôi để Draft vào trong sagadata thì sao "}]}]},"mentioned_items":[],"structured_output_nodes":[{"id":1,"type":0,"content":"## KHÔNG nên để Draft vào SagaData!

### **Vấn đề khi lưu Draft:**

#### **1. Violation of Saga Pattern:**
```csharp
// ❌ BAD - Saga không nên lưu business objects
public class BecomeHostSagaData: SagaStateMachineInstance
{
 public BecomeHostDraft Draft { get; set; } // ❌ Sai design
}
```

#### **2. Performance Issues:**
- **Serialization overhead**: Draft object lớn
- **Database bloat**: Saga table sẽ rất nặng
- **Memory usage**: Tốn RAM không cần thiết

#### **3. Data Duplication:**
- Draft đã có trong Redis
- Saga lưu duplicate → inconsistency risk
- Khó sync khi Draft thay đổi

#### **4. Coupling Issues:**
- Saga phụ thuộc vào Draft structure
- Thay đổi Draft → phải update Saga
- Violate separation of concerns

### **Cách đúng:**

<augment_code_snippet path="services/OrchestratorService/Orchestrator.Api/Sagas/BecomeHostSaga.cs" mode="EDIT">
```csharp
public class BecomeHostSagaData: SagaStateMachineInstance
{
 // ✅ Chỉ lưu essential IDs và state
 public Guid CorrelationId { get; set; }
 public string CurrentState { get; set; }
 public int HostId { get; set; }
 public int PropertyId { get; set; }
 public DateTime StartedAt { get; set; }

 // ❌ KHÔNG lưu Draft object
 // public BecomeHostDraft Draft { get; set; }
}
```
</augment_code_snippet>

### **Flow đúng:**
```
1. Controller: Draft → BecomeHostStarted event
2. Saga: Extract cần thiết từ event → Lưu vào SagaData
3. Saga: Sử dụng data đã extract cho workflow
4. Controller: Xóa Draft khỏi Redis sau khi publish
```

### **Nếu cần access Draft data:**
<augment_code_snippet path="services/OrchestratorService/Orchestrator.Api/Sagas/BecomeHostSaga.cs" mode="EDIT">
```csharp
// ✅ Extract data cần thiết từ event
Initially(
 When(Started)
 .Then(context => { 
 context.Saga.HostId = context.Message.HostId;
 context.Saga.PropertyName = context.Message.Name;
 context.Saga.PropertyTypeId = context.Message.PropertyTypeId;
 // Chỉ lưu fields cần thiết
 })
);
```
</augment_code_snippet>

**Nguyên tắc**: Saga chỉ lưu minimal state để coordinate workflow, không phải data warehouse!
