,"text":"thế ở đây trong trương hợp PropertyNotFound thì tôi xử lý lỗi trong consumer như nào"}]}]},"mentioned_items":[],"structured_output_nodes":[{"id":1,"type":0,"content":"## Xử lý PropertyNotFound trong Consumer

### **Cách 1: Response với Error Event (Recommended)**

<augment_code_snippet path="services/PropertyService/Property.Application/Consumers/AddRentalUnitConsumer.cs" mode="EDIT">
```csharp
public async Task Consume(ConsumeContext<AddRentalUnit> context)
{
 var property = await propertyRepository.GetByIdAsync(context.Message.PropertyId);
 if (property is null) 
 {
 // ✅ Response với error event
 await context.RespondAsync<AddRentalUnitFailed>(new
 {
 CorrelationId = context.Message.CorrelationId,
 PropertyId = context.Message.PropertyId,
 ErrorCode = PropertyErrors.PropertyNotFound.Code,
 ErrorMessage = PropertyErrors.PropertyNotFound.Description
 });
 return; // Không throw exception
 }

 // Business logic tiếp tục...
 if (context.Message.IsRoomBasedProperty)
 {
 var roomRentalUnit = new RoomRentalUnit(/*...*/);
 property.AddRentalUnit(roomRentalUnit);
 }

 await propertyRepository.Update(property);
 await unitOfWork.SaveChangesAsync();

 // Success response
 await context.RespondAsync<RentalUnitAdded>(new
 {
 CorrelationId = context.Message.CorrelationId,
 PropertyId = property.Id,
 RentalUnitId = roomRentalUnit.Id
 });
}
```
</augment_code_snippet>

### **Cách 2: Throw Exception (MassTransit sẽ retry)**

<augment_code_snippet path="services/PropertyService/Property.Application/Consumers/AddRentalUnitConsumer.cs" mode="EDIT">
```csharp
public async Task Consume(ConsumeContext<AddRentalUnit> context)
{
 var property = await propertyRepository.GetByIdAsync(context.Message.PropertyId);
 if (property is null) 
 {
 // ✅ Throw business exception
 throw new PropertyNotFoundException($"Property with ID {context.Message.PropertyId} not found");
 }

 // Business logic...
}
```
</augment_code_snippet>

### **Tạo Error Events:**

<augment_code_snippet path="shared/Contracts/Events/AddRentalUnitFailed.cs" mode="EDIT">
```csharp
public record AddRentalUnitFailed
(
 Guid CorrelationId,
 int PropertyId,
 string ErrorCode,
 string ErrorMessage
);
```
</augment_code_snippet>

### **Trong Saga handle error:**

<augment_code_snippet path="services/OrchestratorService/Orchestrator.Api/Sagas/BecomeHostSaga.cs" mode="EDIT">
```csharp
During(CreatingRentalUnits,
 When(RentalUnitAdded)
 .TransitionTo(Completed)
 .Finalize(),

 When(AddRentalUnitFailed)
 .Then(context => {
 // Log error
 Console.WriteLine($"Failed to add rental unit: {context.Message.ErrorMessage}");
 })
 .TransitionTo(Failed)
 .Finalize()
);
```
</augment_code_snippet>

### **Custom Exception:**

<augment_code_snippet path="services/PropertyService/Property.Application/Exceptions/PropertyNotFoundException.cs" mode="EDIT">
```csharp
public class PropertyNotFoundException : Exception
{
 public PropertyNotFoundException(string message) : base(message) { }
}
```
</augment_code_snippet>

**Recommendation**: Dùng **Cách 1** để Saga có thể handle error gracefully thay vì rely on exception/retry mechanism!
