public record AddRentalUnit( // ✅ Command Event
 Guid CorrelationId,
 int PropertyId, // ✅ Target để add rental unit
 int MaxAdults, // ✅ Business data
 int MaxChildren, // ✅ Business data
 int Size, // ✅ Business data
 int BedroomsCount, // ✅ Business data
 int BathroomsCount, // ✅ Business data
 bool IsRoomBasedProperty,// ✅ Business logic flag
 int Quantity, // ✅ Business data
 bool SharedBathroom, // ✅ Business data
