### **2. Hoàn thiện Saga Logic:**

<augment_code_snippet path="services/OrchestratorService/Orchestrator.Api/Sagas/BecomeHostSaga.cs" mode="EDIT">
```csharp
public class BecomeHostSaga : MassTransitStateMachine<BecomeHostSagaData>
{
 public State CreatingProperty { get; private set; }
 public State AddingRentalUnit { get; private set; }
 public State Completed { get; private set; }
 public State Failed { get; private set; }

 public Event<BecomeHostStarted> Started { get; private set; }
 public Event<PropertyCreated> PropertyCreated { get; private set; }
 public Event<RentalUnitAdded> RentalUnitAdded { get; private set; }
 public Event<PropertyCreationFailed> PropertyCreationFailed { get; private set; }
 public Event<AddRentalUnitFailed> AddRentalUnitFailed { get; private set; }

 public BecomeHostSaga()
 {
 InstanceState(x => x.CurrentState);

 Event(() => Started, x => x.CorrelateById(m => m.Message.CorrelationId));
 Event(() => PropertyCreated, x => x.CorrelateById(m => m.Message.CorrelationId));
 Event(() => RentalUnitAdded, x => x.CorrelateById(m => m.Message.CorrelationId));
 Event(() => PropertyCreationFailed, x => x.CorrelateById(m => m.Message.CorrelationId));
 Event(() => AddRentalUnitFailed, x => x.CorrelateById(m => m.Message.CorrelationId));

 Initially(
 When(Started)
 .Then(context => {
 // Extract tất cả data từ BecomeHostStarted
 context.Saga.HostId = context.Message.HostId;
 context.Saga.PropertyName = context.Message.Name;
 context.Saga.PropertyTypeId = context.Message.PropertyTypeId;
 context.Saga.Address = context.Message.Address;
 context.Saga.City = context.Message.City;
 context.Saga.Country = context.Message.Country;
 context.Saga.PostCode = context.Message.PostCode;
 context.Saga.CheckInTimeFrom = context.Message.CheckInTimeFrom;
 context.Saga.CheckInTimeUntil = context.Message.CheckInTimeUntil;
 context.Saga.CheckOutTimeFrom = context.Message.CheckOutTimeFrom;
 context.Saga.CheckOutTimeUntil = context.Message.CheckOutTimeUntil;
 context.Saga.PetAllowed = context.Message.PetAllowed;
 context.Saga.SmokingAllowed = context.Message.SmokingAllowed;
 context.Saga.PartyAllowed = context.Message.PartyAllowed;
 context.Saga.AgeRestriction = context.Message.AgeRestriction;
 context.Saga.FloorNumber = context.Message.FloorNumber;

 // RentalUnit data từ Draft
 context.Saga.MaxAdults = context.Message.MaxAdults;
 context.Saga.MaxChildren = context.Message.MaxChildren;
 context.Saga.Size = context.Message.Size;
 context.Saga.BedroomsCount = context.Message.BedroomsCount;
 context.Saga.BathroomsCount = context.Message.BathroomsCount;
 context.Saga.IsRoomBasedProperty = context.Message.IsRoomBasedProperty;
 context.Saga.Quantity = context.Message.Quantity;
 context.Saga.SharedBathroom = context.Message.SharedBathroom;
 context.Saga.PricePerNight = context.Message.PricePerNight;
 })
 .TransitionTo(CreatingProperty)
 .Publish(context => context.Message.ToCreateProperty())
 );

 During(CreatingProperty,
 When(PropertyCreated)
 .Then(context => {
 context.Saga.PropertyId = context.Message.PropertyId;
 })
 .TransitionTo(AddingRentalUnit)
 .Publish(context => new AddRentalUnit(
 context.Saga.CorrelationId,
 context.Saga.PropertyId,
 context.Saga.MaxAdults,
 context.Saga.MaxChildren,
 context.Saga.Size,
 context.Saga.BedroomsCount,
 context.Saga.BathroomsCount,
 context.Saga.IsRoomBasedProperty,
 context.Saga.Quantity,
 context.Saga.SharedBathroom,
 context.Saga.PricePerNight,
 "USD"
 )),

 When(PropertyCreationFailed)
 .TransitionTo(Failed)
 .Finalize()
 );

 During(AddingRentalUnit,
 When(RentalUnitAdded)
 .Then(context => {
 context.Saga.RentalUnitId = context.Message.RentalUnitId;
 })
 .TransitionTo(Completed)
 .Finalize(),

 When(AddRentalUnitFailed)
 .TransitionTo(Failed)
 .Finalize()
 );
 }
}
```
</augment_code_snippet>

