### **Giải pháp 1: Shared DTOs (Recommended)**

````csharp path=shared/Contracts/DTOs/PropertyCreationData.cs mode=EDIT
public record PropertyCreationData
{
 public int HostId { get; init; }
 public string Name { get; init; }
 public int PropertyTypeId { get; init; }
 public LocationDto Location { get; init; }
 public HouseRuleDto HouseRule { get; init; }
 public RentalUnitDto RentalUnit { get; init; }
 public decimal PricePerNight { get; init; }
}

public record LocationDto(string Address, string City, string Country, int PostCode);
public record HouseRuleDto(TimeSpan CheckInFrom, TimeSpan CheckInUntil, /* ... */);
public record RentalUnitDto(int MaxAdults, int MaxChildren, /* ... */);
````

