### **Simplify SagaData:**

````csharp path=services/OrchestratorService/Orchestrator.Api/Sagas/BecomeHostSaga.cs mode=EDIT
public class BecomeHostSagaData: SagaStateMachineInstance
{
 public Guid CorrelationId { get; set; }
 public string CurrentState { get; set; }

 // ✅ Chỉ 1 object thay vì 20+ fields
 public PropertyCreationData CreationData { get; set; }

 // Response IDs
 public int PropertyId { get; set; }
 public int RentalUnitId { get; set; }
}

Initially(
 When(Started)
 .Then(context => {
 context.Saga.CreationData = context.Message.Data; // ✅ Simple assignment
 })
 .TransitionTo(CreatingProperty)
 .Publish(context => new CreateProperty(
 context.Saga.CorrelationId,
 context.Saga.CreationData // ✅ Pass through
 ))
);
````

